function analyzeLogo(img){const c=document.createElement('canvas'),ratio=Math.min(1,320/Math.max(img.width,img.height));c.width=Math.max(2,Math.round(img.width*ratio));c.height=Math.max(2,Math.round(img.height*ratio));const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(img,0,0,c.width,c.height);const data=cx.getImageData(0,0,c.width,c.height).data,detection=BackgroundAnalysis.analyze(data,c.width,c.height);return {...detection,inks:PantoneApprox.extractInks(data,c.width,c.height,detection)};}
function prepareLogo(){if(!logoImg)return logoImg;if(!state.removeWhite&&state.bgDetection?.kind!=='transparent')return logoImg;const rgb=state.bgDetection?.rgb||[255,255,255],key=state.logo+'|'+rgb.join(',')+'|'+state.removeWhite+'|'+state.bgDetection?.kind;if(processedKey===key&&processedLogo)return processedLogo;const layer=document.createElement('canvas');const ratio=Math.min(1,1600/Math.max(logoImg.width,logoImg.height));layer.width=Math.round(logoImg.width*ratio);layer.height=Math.round(logoImg.height*ratio);const c=layer.getContext('2d',{willReadFrequently:true});c.drawImage(logoImg,0,0,layer.width,layer.height);const pixels=c.getImageData(0,0,layer.width,layer.height),d=pixels.data;if(state.removeWhite){const {mask}=BackgroundAnalysis.edgeMask(d,layer.width,layer.height,rgb,32);for(let i=0;i<mask.length;i++)if(mask[i])d[i*4+3]=0;}c.putImageData(pixels,0,0);let x0=layer.width,y0=layer.height,x1=-1,y1=-1;for(let y=0;y<layer.height;y++)for(let x=0;x<layer.width;x++){if(d[(y*layer.width+x)*4+3]>24){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y);}}if(x1>=x0&&y1>=y0){const pad=Math.max(2,Math.round(Math.max(x1-x0,y1-y0)*.025));x0=Math.max(0,x0-pad);y0=Math.max(0,y0-pad);x1=Math.min(layer.width-1,x1+pad);y1=Math.min(layer.height-1,y1+pad);const fitted=document.createElement('canvas');fitted.width=x1-x0+1;fitted.height=y1-y0+1;fitted.getContext('2d').drawImage(layer,x0,y0,fitted.width,fitted.height,0,0,fitted.width,fitted.height);processedLogo=fitted;}else processedLogo=layer;processedKey=key;return processedLogo;}
function backgroundFeedback(){const detection=state.bgDetection;$('backgroundResult').hidden=!detection||state.removed;$('backgroundChoice').hidden=!state.bgDecisionPending;$('next').disabled=state.bgDecisionPending;$('removeWhite').disabled=state.removed||!detection||detection.kind==='transparent'||detection.kind==='ambiguous';if(!detection)return;let message='';if(state.bgSource==='manual')message='Ambalaj rengi seçiminizle güncellendi: '+state.bg.toUpperCase();else if(detection.kind==='color')message='Logonuzun zemin rengi ambalaja uygulandı: '+detection.color.toUpperCase();else if(detection.kind==='white')message='Beyaz logo zemini algılandı; ambalaj beyaz.';else if(detection.kind==='transparent')message='Şeffaf logo algılandı; ambalaj beyaz.';else message=detection.reason==='photo-or-proof'?'Bu görsel fotoğraf veya çok öğeli grafik olabilir. Yalnız logo/ön yüz tasarımını kırpıp yükleyin ya da ambalaj rengini seçin.':'Zemin birden fazla renk içeriyor; otomatik renk seçilmedi.';$('backgroundResult').textContent=message;$('backgroundResult').style.borderLeft='10px solid '+state.bg;const change=document.createElement('button');change.type='button';change.textContent='Değiştir';change.className='backgroundChange';change.onclick=()=>{panels[1].open=true;setTimeout(()=>panels[1].scrollIntoView({behavior:'smooth',block:'nearest'}),40);};$('backgroundResult').append(change);}
function renderSuggestions(){const box=$('colorSuggestions');box.hidden=state.removed||!state.bgDetection;const rows=$('suggestionRows');rows.replaceChildren();if(box.hidden)return;const catalog=window.PANTONE_APPROX_DATA||[];if(!catalog.length){rows.textContent='Yaklaşık renk referansları yüklenemedi.';return;}const colors=[];if(state.bgDetection.kind==='color')colors.push({label:'Görsel zemini',rgb:state.bgDetection.rgb});for(const [i,ink] of (state.bgDetection.inks||[]).entries())colors.push({label:'Logo rengi '+(i+1),rgb:ink.rgb});if(!colors.length){rows.textContent='Düz ve anlamlı bir logo rengi bulunamadı. Grafik dosyasının teknik incelemesi gerekir.';return;}for(const item of colors){const row=document.createElement('div');row.className='suggestionRow';const swatch=document.createElement('i');swatch.style.background=BackgroundAnalysis.hex(item.rgb);const label=document.createElement('span');label.textContent=item.label+' '+BackgroundAnalysis.hex(item.rgb).toUpperCase();const matches=PantoneApprox.suggest(item.rgb,catalog,3);const desc=document.createElement('small');desc.textContent=matches.map(m=>m.code+' (ΔE '+m.distance.toFixed(1)+')').join(' · ');if(matches[0].distance>12)desc.textContent+=' — yakınlık zayıf; elle doğrulama gerekir';row.append(swatch,label,desc);rows.append(row);}}
