const warped=document.createElement('canvas');warped.width=1600;warped.height=850;const wc=warped.getContext('2d');for(let x=240;x<1360;x+=4){const n=(x-800)/560,scale=1-.055*n*n,offset=425*(1-scale);wc.drawImage(ink,x,0,4,850,x,offset,4,850*scale);}wc.globalCompositeOperation='destination-in';wc.drawImage(asset,0,0);const printed=document.createElement('canvas');printed.width=1600;printed.height=850;const pc=printed.getContext('2d');pc.drawImage(warped,0,0);pc.globalCompositeOperation='multiply';pc.drawImage(material,0,0);pc.globalCompositeOperation='destination-in';pc.drawImage(warped,0,0);ctx.drawImage(printed,0,0);
