function refresh(){for(const [id,key] of [['size','size'],['rotation','rotation'],['text','text'],['font','font'],['textSize','textSize']])$(id).value=state[key];$('sizeValue').textContent='%'+state.size;$('rotationValue').textContent=state.rotation+'°';$('filename').textContent=state.removed?'Henüz logo yok':state.logoName;$('remove').disabled=state.removed;$('bgPantone').value=state.bgPantone;$('textPantone').value=state.textPantone;$('previewCaption').textContent=(palette.find(p=>p[0]===state.bg)?.[1]||'Seçili renk')+' ambalaj'+(state.removed?' · Logonuzla başlayın':' · Görsel önizleme');$('bgName').textContent=palette.find(p=>p[0]===state.bg)?.[1]||state.bg.toUpperCase();$('bgCustom').value=state.bg;$('textCustom').value=state.textColor;$('removeWhite').checked=state.removeWhite;$('removeWhite').disabled=state.removed;$('undo').disabled=!history.length;$('recolorHint').textContent=state.recolor?'Orijinal renkler korunur. Tek renkli SVG üzerinde isterseniz paletten yeni bir renk seçebilirsiniz.':'Bu dosyada renk değiştirme kapalıdır. Renkli veya raster logonuzu istediğiniz renkte yükleyin.';document.querySelectorAll('[data-color-key]').forEach(b=>{b.classList.toggle('selected',state[b.dataset.colorKey]===b.dataset.color);b.disabled=b.dataset.colorKey==='color'&&!state.recolor;});backgroundFeedback();renderSuggestions();renderPantoneLookup('bgPantone');renderPantoneLookup('textPantone');draw();}
for(const [id,key,items] of [['backgrounds','bg',palette.slice(0,5)],['logoColors','color',palette],['textColors','textColor',palette.slice(0,5)]])for(const [color,name] of items){const b=document.createElement('button');b.style.background=color;b.title=name;b.setAttribute('aria-label',name);b.dataset.colorKey=key;b.dataset.color=color;b.onclick=()=>{if(key==='bg'){chooseBackground(color);return;}remember();state[key]=color;if(key==='color')state.recolorApplied=true;refresh();};$(id).appendChild(b);}
for(const [id,key,numeric] of [['size','size',true],['rotation','rotation',true],['text','text',false],['font','font',false],['textSize','textSize',true]]){$(id).addEventListener('focus',()=>remember());$(id).oninput=()=>{state[key]=numeric?Number($(id).value):$(id).value;refresh();};}
$('upload').onchange=async e=>{const f=e.target.files[0];if(!f)return;const ticket=++loading;try{if(f.size>5*1024*1024)throw Error('Dosya en fazla 5 MB olmalı.');if(!/\.(png|jpe?g|svg)$/i.test(f.name))throw Error('Yalnızca PNG, JPG veya SVG yükleyin.');let data,recolor=false;if(/\.svg$/i.test(f.name)){({data,recolor}=svgSafe(await f.text()));}else{data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});if(!/^data:image\/(png|jpeg);/.test(data))throw Error('Dosya türü desteklenmiyor.');}const img=await loadImage(data);if(ticket!==loading)return;remember();state.logo=data;state.logoName=f.name;state.recolor=recolor;state.recolorApplied=false;state.bgDetection=analyzeLogo(img);state.bgSource='auto';state.bg=state.bgDetection.color||'#ffffff';state.bgPantone='';state.bgDecisionPending=state.bgDetection.kind==='ambiguous';state.removeWhite=['white','color'].includes(state.bgDetection.kind);state.removed=false;processedLogo=null;processedKey=null;state.rotation=0;logoImg=img;refresh();status('Logo cihazınızda yüklendi; sunucuya gönderilmedi.');}catch(err){status(err.message||'Dosya okunamadı.');}e.target.value='';};
$('remove').onclick=()=>{remember();loading++;state.removed=true;refresh();};$('addText').onclick=()=>{$('text').focus();$('text').select();};document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>{remember();state.x={left:560,center:800,right:1040}[b.dataset.align];refresh();});
$('undo').onclick=async()=>{if(!history.length)return;const ticket=++loading,target=history.pop();const img=target.logo?await loadImage(target.logo):null;if(ticket!==loading)return;state=target;logoImg=img;refresh();status('Son düzenleme geri alındı.');};$('reset').onclick=()=>{remember();loading++;state={...initial};logoImg=null;refresh();status('Beyaz ve yazısız başlangıca dönüldü.');};
let drag=null;canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*1600/r.width,y=(e.clientY-r.top)*850/r.height;const target=state.text&&Math.abs(y-state.ty)<70&&Math.abs(x-state.tx)<400?'text':'logo';if(target==='logo'&&state.removed)return;remember();drag={target,dx:x-(target==='text'?state.tx:state.x),dy:y-(target==='text'?state.ty:state.y)};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;const r=canvas.getBoundingClientRect(),x=Math.max(350,Math.min(1250,(e.clientX-r.left)*1600/r.width-drag.dx)),y=Math.max(250,Math.min(590,(e.clientY-r.top)*850/r.height-drag.dy));if(drag.target==='text'){state.tx=x;state.ty=y;}else{state.x=x;state.y=y;}draw();};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
function imageData(){draw(false);const d=canvas.toDataURL('image/png');draw();return d;}$('download').onclick=()=>{const a=document.createElement('a');a.download='HijyenLab-gorsel-onizleme-baskiya-hazir-degil.png';a.href=imageData();a.click();status('Görsel önizleme indirildi. Baskıya hazır grafik dosyası değildir.');};
const districts={'İstanbul':['Kadıköy','Beşiktaş','Diğer ilçe'],'Muğla':['Bodrum','Menteşe','Marmaris','Fethiye','Diğer ilçe'],'Ankara':['Çankaya','Diğer ilçe'],'İzmir':['Konak','Diğer ilçe'],'Antalya':['Muratpaşa','Diğer ilçe'],'Diğer il':['Diğer ilçe']};function setDistrict(){const el=$('district');el.replaceChildren();for(const name of districts[$('province').value])el.add(new Option(name,name));calculate();}
function pricing(q,bg,province,district,cliche,inks){if(!Number.isInteger(inks)||inks<1||inks>6)throw Error('Baskı rengi sayısı 1–6 arasında tam sayı olmalı.');if(!['new','existing'].includes(cliche))throw Error('Geçerli bir klişe durumu seçin.');const minimum=bg==='#ffffff'?5200:10000;if(!Number.isInteger(q)||q<minimum||q>1000000)throw Error(`${bg==='#ffffff'?'Beyaz':'Renkli'} zemin için adet ${minimum.toLocaleString('tr-TR')}–1.000.000 arasında tam sayı olmalı.`);const boxes=Math.ceil(q/400),base=q*290,color=bg==='#ffffff'?0:q*50,plate=inks*100000,shipping=province==='Muğla'&&district==='Bodrum'?0:boxes*20000,subtotal=base+color+plate+shipping,tax=Math.round(subtotal*.2);return {boxes,base,color,plate,shipping,subtotal,tax,total:subtotal+tax,minimum,platePending:cliche==='existing'};}

const money=v=>(v/100).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})+' TL';let latest=null;
function effectiveBackground(){return state.bgPantone.trim()?'pantone-request':state.bg;}
function calculate(){const minimum=effectiveBackground()==='#ffffff'?5200:10000;$('qty').min=minimum;$('minimumNote').textContent=`En az ${minimum.toLocaleString('tr-TR')} adet • ${minimum===5200?'beyaz':'renkli / Pantone talebi'} zemin`;$('useMinimum').textContent=`${minimum.toLocaleString('tr-TR')} adetle hesapla`;$('useMinimum').hidden=Number($('qty').value)>=minimum;try{const q=Number($('qty').value),inks=Number($('inks').value);latest=pricing(q,effectiveBackground(),$('province').value,$('district').value,$('cliche').value,inks);$('boxes').textContent=`400 adet/koli → ${latest.boxes} koli`;$('review').disabled=false;const rows=[['Ürün bedeli',latest.base,`${q.toLocaleString('tr-TR')} × 2,90 TL`],['Renkli zemin farkı',latest.color,latest.color?`${q.toLocaleString('tr-TR')} × 0,50 TL`:'Beyaz zemin • fark yok'],['Klişe bedeli',latest.plate,latest.platePending?'Kontrol bekliyor; geçici yeni klişe bedeli dahil. Onaylanırsa düşebilir.':`${inks} renk × 1.000,00 TL`],['Kargo',latest.shipping,latest.shipping?`${latest.boxes} koli × 200,00 TL`:'Bodrum • HijyenLab teslimatı'],['Ara toplam',latest.subtotal,''],['KDV (%20)',latest.tax,''],['Tahmini genel toplam',latest.total,'']];$('breakdown').replaceChildren();for(const [label,value,note] of rows){const row=document.createElement('div');row.className='priceRow'+(label==='Tahmini genel toplam'?' total':'');const l=document.createElement('span');l.textContent=label;if(note){const n=document.createElement('small');n.textContent=note;l.append(n);}const v=document.createElement('strong');v.textContent=money(value);row.append(l,v);$('breakdown').append(row);}status('');}catch(e){latest=null;$('review').disabled=true;$('boxes').textContent='';$('breakdown').textContent=e.message;status(e.message);}}

$('province').onchange=setDistrict;for(const id of ['qty','district','cliche','inks'])$(id).oninput=calculate;
function go(n){if(n>1&&state.bgDecisionPending){status('Önce ambalaj için beyaz veya kendi seçtiğiniz zemin rengini belirleyin.');return;}if(n===3&&!latest){status('Önce geçerli bir adet seçin.');return;}step=n;['design','pricing','summary'].forEach((id,i)=>$(id).hidden=i+1!==n);document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===n));if(n===2){$('mini').src=imageData();calculate();}if(n===3){$('finalImage').src=imageData();$('finalDetails').replaceChildren();for(const s of [`${$('qty').value} adet • ${$('province').value} / ${$('district').value}`,`Tahmini genel toplam: ${money(latest.total)} — kesin teklif değildir`,`Klişe: ${$('cliche').selectedOptions[0].textContent} • ${$('inks').value} örnek baskı rengi`,...(state.bgPantone?[`Zemin Pantone talebi: ${state.bgPantone} — henüz doğrulanmadı`]:[]),...(state.textPantone?[`Yazı Pantone talebi: ${state.textPantone} — henüz doğrulanmadı`]:[])]){const p=document.createElement('p');p.textContent=s;$('finalDetails').append(p);}status('Gönderim yapılmadı. Bu yalnızca yerel demo özetidir.');}else status('');draw();window.scrollTo({top:0,behavior:'smooth'});}
$('useMinimum').onclick=()=>{$('qty').value=effectiveBackground()==='#ffffff'?5200:10000;calculate();};$('next').onclick=()=>go(2);$('back').onclick=$('summaryBack').onclick=()=>go(1);$('review').onclick=()=>go(3);document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{calculate();go(Number(b.dataset.step));});setDistrict();refresh();go(1);

$('originalColors').onclick=()=>{remember();state.recolorApplied=false;refresh();};
for(const id of ['bgPantone','textPantone']){$(id).onfocus=()=>remember();$(id).oninput=()=>{state[id]=$(id).value;renderPantoneLookup(id);};}
const panels=[...document.querySelectorAll('.editPanel')];panels.forEach(p=>p.addEventListener('toggle',()=>{if(p.open)panels.filter(q=>q!==p).forEach(q=>q.open=false);}));document.querySelectorAll('[data-open-panel]').forEach(b=>b.onclick=()=>{const p=panels[Number(b.dataset.openPanel)];p.open=true;setTimeout(()=>p.scrollIntoView({behavior:'smooth',block:'nearest'}),40);});

$('removeWhite').onchange=()=>{remember();state.removeWhite=$('removeWhite').checked;refresh();status(state.removeWhite?'Logo zemini ambalajla birleştirildi. Logo ayrıntıları etkilenirse bu seçimi kapatın.':'Orijinal logo zemini geri getirildi.');};for(const [id,key] of [['bgCustom','bg'],['textCustom','textColor']]){$(id).onchange=()=>{if(key==='bg'){chooseBackground($(id).value);return;}remember();state[key]=$(id).value;refresh();};}

$('chooseWhite').onclick=()=>chooseBackground('#ffffff');$('chooseColor').onclick=()=>{panels[1].open=true;setTimeout(()=>panels[1].scrollIntoView({behavior:'smooth',block:'nearest'}),40);status('Paletten veya renk seçiciden ambalaj renginizi seçin.');};

function renderPantoneLookup(id){const target=$(id+'Result');target.replaceChildren();const result=PantoneApprox.lookup(state[id],window.PANTONE_APPROX_DATA||[]);if(result.status==='empty')return;const messages={'unsupported-u':'U serisi bu referans kümesinde desteklenmiyor. C karşılığı varsayılmadı.','suffix-required':'Kodun sonuna C veya U serisini ekleyin (ör. 186 C).','special-ink':'Metalik/floresan mürekkepler için ekran eşlemesi sunulmuyor.','unknown':'Bu kod yaklaşık referans listesinde bulunamadı. Kod not olarak korunur.'};if(result.status!=='approximate'){target.textContent=messages[result.status];return;}const m=result.match,label=document.createElement('span');label.textContent=m.code+' · yaklaşık ekran rengi '+m.hex.toUpperCase();const swatch=document.createElement('i');swatch.style.background=m.hex;const apply=document.createElement('button');apply.type='button';apply.textContent='Önizlemeye uygula';apply.onclick=()=>{remember();if(id==='bgPantone'){state.bg=m.hex;state.bgSource='manual';state.bgDecisionPending=false;}else state.textColor=m.hex;refresh();};target.append(swatch,label,apply);}
